<template>
  <div class="student-dashboard">
    <section class="hero-card" :style="{ backgroundImage: `url(${heroImage})` }"><div><h3>你好，{{ authStore.displayName }}同学 <span>👋</span></h3></div></section>
    <div v-if="errorMessage" class="error">{{ errorMessage }}</div><div v-if="loading" class="loading">正在加载学习数据…</div>
    <template v-else>
      <section class="stats-grid"><button v-for="stat in stats" :key="stat.label" class="stat-card" :class="`stat-${stat.tone}`" @click="stat.path && router.push(stat.path)"><span class="stat-icon"><el-icon><component :is="stat.icon" /></el-icon></span><strong>{{ stat.value }}</strong><small>{{ stat.label }}</small><el-icon class="arrow"><ArrowRight /></el-icon></button></section>
      <div class="dashboard-grid"><div class="dashboard-main">
        <section class="panel progress-panel"><div class="panel-heading"><h2><TrendCharts /> 我的学习进度</h2><span>持续保持学习节奏</span></div><div class="progress-content"><div class="progress-ring" :style="{ '--progress': `${progress}%` }"><strong>{{ progress }}%</strong><small>整体完成度</small></div><div class="progress-bars"><div v-for="item in progressItems" :key="item.label"><label><span>{{ item.label }}</span><b>{{ item.value }} / {{ item.total }}</b></label><i><em :style="{ width: `${item.percent}%`, background: item.color }"></em></i></div></div><div class="progress-summary"><div><Clock /><span>本周学习时长<strong>{{ scores.length ? `${scores.length * 2}h 32min` : '—' }}</strong></span></div><div><CircleCheck /><span>已完成任务<strong>{{ completedAssignments }}</strong></span></div><div><Loading /><span>进行中任务<strong>{{ inProgressAssignments }}</strong></span></div></div></div></section>
        <section class="panel"><div class="panel-heading"><h2><Reading /> 我的课程</h2><RouterLink to="/student/courses">查看全部 <ArrowRight /></RouterLink></div><div v-if="courses.length" class="course-grid"><article v-for="course in courses.slice(0,4)" :key="course.id" class="course-card" @click="router.push(`/student/course/${course.id}`)"><div class="course-cover" :class="`cover-${course.id % 4}`"><span>{{ course.code?.slice(0,2) || 'GD' }}</span></div><div class="course-body"><h3>{{ course.name }}</h3><p>{{ course.teacherName || '任课教师' }}</p><label>进度 {{ courseProgress(course.id) }}%</label><i><em :style="{width:`${courseProgress(course.id)}%`}"></em></i><button>进入课程 <ArrowRight /></button></div></article></div><el-empty v-else description="暂无课程" /></section>
      </div><aside class="dashboard-side"><section class="panel"><div class="panel-heading"><h2><List /> 待办事项</h2><RouterLink to="/student/dashboard">查看全部 <ArrowRight /></RouterLink></div><div v-if="todoAssignments.length" class="todo-list"><button v-for="item in todoAssignments.slice(0,4)" :key="item.id" @click="router.push(`/student/assignment/${item.id}`)"><i :class="item.submitted?'done':''"></i><span><strong>{{ item.title }}</strong><small>{{ item.submitted ? '已提交' : '待完成' }}</small></span><time>{{ formatDeadline(item.deadline) }}</time><ArrowRight /></button></div><el-empty v-else description="暂无待办事项" /></section><section class="panel focus-panel"><div class="panel-heading"><h2><FolderOpened /> 当前项目</h2></div><template v-if="currentProject"><div class="focus-cover cover-2"><span>{{ currentProject.courseCode?.slice(0,2) || 'PJ' }}</span></div><h3>{{ currentProject.title }}</h3><p>{{ currentProject.courseName || '课程作业' }} · 截止 {{ formatDeadline(currentProject.deadline) }}</p><label>项目状态 <b>{{ currentProject.submitted || currentProject.scorePublished ? '已提交' : '进行中' }}</b></label><i><em :style="{width:currentProject.submitted||currentProject.scorePublished?'100%':'45%'}"></em></i><button class="focus-button" @click="router.push(`/student/assignment/${currentProject.id}`)">进入项目工作台 <ArrowRight /></button></template><el-empty v-else description="打开作业后将在这里继续" /></section></aside></div>
      <section class="assistant-card"><div><h2><MagicStick /> WiseCollab 智能学习助手</h2><p>遇到学习难题？我来帮你寻找资源、解答问题、规划学习路径。</p><div class="assistant-input">例如：我正在做 Vue 项目，有什么学习资源？<button>➤</button></div></div><div class="chips"><span>推荐 Vue 学习资源</span><span>寻找 PBL 项目案例</span><span>查看赛事资料</span><span>学习路线规划</span></div><b class="bot">●</b></section>
    </template>
