<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, CircleCheck, Clock, FolderOpened, List, Loading, MagicStick, Reading, TrendCharts } from '@element-plus/icons-vue'
import { useAuthStore } from '@/stores/auth'; 
import { getAssignments, getCourses, getScores } from '@/api/student'; 
import { getErrorMessage } from '@/api/response'; 
import { getRecentProject } from '@/utils/studentRecentProject'
import heroImage from '@/assets/student-hero.png'
const router=useRouter(), authStore=useAuthStore(), courses=ref([]), assignments=ref([]), scores=ref([]), loading=ref(false), errorMessage=ref('')
const completedAssignments=computed(()=>assignments.value.filter(x=>x.submitted||x.scorePublished).length), inProgressAssignments=computed(()=>assignments.value.filter(x=>!x.submitted&&!x.scorePublished).length), progress=computed(()=>assignments.value.length?Math.round(completedAssignments.value/assignments.value.length*100):0), todoAssignments=computed(()=>assignments.value.filter(x=>!x.scorePublished).sort((a,b)=>new Date(a.deadline||0)-new Date(b.deadline||0)))
const currentProject=computed(()=>{const recent=getRecentProject();if(!recent)return null;const assignment=assignments.value.find(x=>String(x.id)===recent.assignmentId);if(!assignment)return null;const course=courses.value.find(x=>String(x.id)===String(assignment.courseId||recent.courseId));return {...assignment,courseName:assignment.courseName||recent.courseName||course?.name,courseCode:course?.code}})
const stats=computed(()=>[{label:'进行中的课程',value:courses.value.length,tone:'blue',icon:Reading},{label:'待完成作业',value:inProgressAssignments.value,tone:'purple',icon:List},{label:'进行中的项目',value:courses.value.filter(x=>x.projectName).length,tone:'green',icon:CircleCheck},{label:'未读消息',value:0,tone:'orange',icon:MagicStick}])
const progressItems=computed(()=>[{label:'课程学习',value:courses.value.length,total:courses.value.length,color:'#4285dc',percent:courses.value.length?100:0},{label:'项目任务',value:completedAssignments.value,total:assignments.value.length,color:'#35b99f',percent:progress.value},{label:'作业完成',value:completedAssignments.value,total:assignments.value.length,color:'#7857d9',percent:progress.value}])
const courseProgress=id=>{const rows=assignments.value.filter(x=>String(x.courseId)===String(id));return rows.length?Math.round(rows.filter(x=>x.submitted||x.scorePublished).length/rows.length*100):0}; const formatDeadline=v=>v?new Date(v).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'}):'待定'
onMounted(async()=>{loading.value=true;try{courses.value=await getCourses();assignments.value=(await Promise.all(courses.value.map(x=>getAssignments(x.id)))).flat();scores.value=await getScores()}catch(e){errorMessage.value=getErrorMessage(e,'学习数据加载失败')}finally{loading.value=false}})
</script>
